## Task Description

Create `frontend/src/components/ChartWidget.tsx` — a React component that renders a Plotly chart.

**IMPORTANT:** The default `import Plot from 'react-plotly.js'` bundles the full ~4MB `plotly.js` instead of the lighter `plotly.js-dist-min`. You MUST use the factory pattern to use the lighter bundle:

```typescript
import createPlotlyComponent from 'react-plotly.js/factory';
import Plotly from 'plotly.js-dist-min';

const Plot = createPlotlyComponent(Plotly);
```

This wires `react-plotly.js` to use `plotly.js-dist-min` (~1.5MB) rather than the full `plotly.js`.

## The Component

```tsx
import createPlotlyComponent from 'react-plotly.js/factory';
import Plotly from 'plotly.js-dist-min';

const Plot = createPlotlyComponent(Plotly);

interface ChartWidgetProps {
  data: unknown[];
  layout?: Record<string, unknown>;
}

export function ChartWidget({ data, layout }: ChartWidgetProps) {
  return (
    <Plot
      data={data as Plotly.Data[]}
      layout={{ autosize: true, ...layout } as Partial<Plotly.Layout>}
      useResizeHandler
      style={{ width: '100%' }}
      config={{ responsive: true, displayModeBar: true }}
    />
  );
}
```

